/// (sıra, başlık, kategori, dakika, özet, gövde) — peygamber kıssaları, 2. yarı
/// (Mûsâ'dan Hz. Muhammed'e). Anlatım Kur'an'a dayanır; israiliyyât içermez.
const List<(int, String, String, int, String, String)> kStorySeedB = [
  // --- Hz. Mûsâ (a.s.) ---
  (40, "Hz. Mûsâ (a.s.) — Nil'den Saraya", 'Peygamberler', 5,
      "Zulmün ortasında suya bırakılan bebek, Allah'ın vaadiyle anasına döndü ve Firavun'un sarayında büyüdü.",
      "Firavun yeryüzünde azmış, halkını fırkalara ayırıp bir topluluğu güçsüz bırakmış, onların oğullarını boğazlatıyordu (Kasas 4). Allah ise güçsüz sayılanlara iyilik etmeyi ve onları önderler kılmayı diledi (Kasas 5). Mûsâ (a.s.)'nın annesine şöyle vahyetti: “Çocuğu emzir; başına gelecekten korktuğunda onu suya bırak, korkma, üzülme. Biz onu sana döndüreceğiz ve peygamber yapacağız.” (Kasas 7) Bebeği Firavun'un adamları aldı; Firavun'un hanımı “Onu öldürmeyin, belki bize faydalı olur” dedi (Kasas 8-9). Annenin kalbi boşalmıştı; Allah onun kalbini pekiştirdi (Kasas 10). Kız kardeşi bebeği uzaktan gözetledi; Allah daha önce süt annelerin memesini ona yasaklamıştı. Kız kardeşi, “Size ona bakacak bir ev halkı göstereyim mi?” deyince bebek anasına geri verildi; “annenin gözü aydın olsun, üzülmesin, Allah'ın sözünün gerçek olduğunu bilsin” diye (Kasas 11-13; Tâhâ 36-40). Mûsâ erginlik çağına gelince Allah ona hikmet ve ilim verdi (Kasas 14). Bu kıssa, Allah'ın takdirinin zalimin tedbirinden üstün olduğunu gösterir. Kaynak: Kur'an-ı Kerim (Kasas, Tâhâ suresi); Diyanet İslam Ansiklopedisi."),
  (41, 'Hz. Mûsâ (a.s.) — Medyen\'den Tûr\'a', 'Peygamberler', 6,
      "Şehirden kaçan Mûsâ, Medyen'de yıllarca kaldı; Tûr'da Rabbinin sesini işitip peygamberlikle görevlendirildi.",
      "Mûsâ (a.s.) bir gün şehre girdi; kendi kavminden biriyle düşmanından olan bir adamı çekişirken buldu. Kendi adamı ondan yardım isteyince düşmana bir yumruk vurdu ve adam öldü. Mûsâ, “Rabbim! Kendime yazık ettim, beni bağışla” dedi; Allah onu bağışladı (Kasas 15-16). Korku içinde şehirden çıktı, “Rabbim! Beni zalimler topluluğundan kurtar” diye dua etti (Kasas 21) ve Medyen'e yöneldi. Orada iki kadının hayvanlarını suladı, gölgeye çekilip “Rabbim! Bana indireceğin her hayra muhtacım” dedi (Kasas 24). Yaşlı bir adamın yanında sekiz yıl, isterse on yıl çalışmak üzere anlaştı (Kasas 27-28). Süreyi doldurup ailesiyle yola çıktığında Tûr tarafında bir ateş gördü; vadinin sağ yanından, “Ey Mûsâ! Ben âlemlerin Rabbi Allah'ım” diye seslenildi (Kasas 29-30). Elindeki asa yılana döndü, eli bembeyaz çıktı (Tâhâ 17-22). Mûsâ görevine karşı “Rabbim! Göğsümü genişlet, işimi kolaylaştır” diye yalvardı ve kardeşi Hârûn'un yardımcı kılınmasını istedi (Tâhâ 25-36). Kaynak: Kur'an-ı Kerim (Kasas, Tâhâ suresi); Diyanet İslam Ansiklopedisi."),
  (42, 'Hz. Mûsâ (a.s.) — Firavun ile Yüzleşme ve Deniz', 'Peygamberler', 6,
      "Mûsâ ile Hârûn Firavun'a yumuşak söz söyledi; sihirbazlar iman etti, deniz yarıldı, zalim boğuldu.",
      "Allah, Mûsâ ile Hârûn'a Firavun'a gitmelerini emretti: “Doğrusu o azmıştır. Ona yumuşak söz söyleyin, belki öğüt alır veya korkar.” İkisi endişelerini söyleyince Allah, “Korkmayın, Ben sizinle beraberim; işitir ve görürüm” buyurdu (Tâhâ 43-46). Firavun'un çağırdığı sihirbazlar ipleriyle halkın gözünü büyüledi; Mûsâ'nın asası onların uydurduklarını yuttu. Sihirbazlar secdeye kapanıp “Mûsâ ve Hârûn'un Rabbine inandık” dediler; Firavun'un ellerini ayaklarını keseceği tehdidine karşı “Biz ancak Rabbimize döneriz” diyerek direndiler (A'râf 113-126). Allah, Mûsâ'ya kullarını geceleyin yürütmesini emretti. İki topluluk birbirini görünce Mûsâ'nın kavmi “Yakalandık” dedi; Mûsâ ise “Hayır, Rabbim benimle beraberdir, bana yol gösterecektir” dedi. “Asanla denize vur” emriyle deniz yarıldı, her parçası yüce bir dağ gibi oldu; Mûsâ ve beraberindekiler kurtuldu, ötekiler boğuldu (Şuarâ 61-66; Tâhâ 77-78). Firavun boğulurken iman ettiğini söyledi, ancak geç kalmıştı; cesedi sonrakilere ibret kılındı (Yûnus 90-92). Kaynak: Kur'an-ı Kerim (Tâhâ, A'râf, Şuarâ, Yûnus suresi); Diyanet İslam Ansiklopedisi."),
  (43, 'Hz. Mûsâ (a.s.) — Tûr, Levhalar ve Buzağı', 'Peygamberler', 6,
      "Rabbiyle konuşan Mûsâ, kavmi buzağıya yönelince öfkelendi; sonunda tövbe ve merhamet duasıyla hakikate döndü.",
      "Allah, Mûsâ'ya otuz gece vade verdi, sonra on gece ekledi; vade kırk geceye tamamlandı. Mûsâ ayrılırken Hârûn'a “Kavmim içinde benim yerime geç, onları ıslah et” dedi (A'râf 142). Tayin edilen vakitte Rabbi onunla konuştu; Mûsâ “Rabbim! Bana kendini göster” deyince Allah “Sen Beni göremezsin ama dağa bak” buyurdu. Dağ parçalandı, Mûsâ baygın düştü; ayılınca “Seni tenzih ederim, Sana tövbe ettim, ben inananların ilkiyim” dedi (A'râf 143). Allah ona levhalarda öğüt ve hükümleri yazdı (A'râf 145). Mûsâ yokken kavmi, ziynetlerinden böğüren bir buzağı heykeli yapıp onu tanrı edindi (A'râf 148). Mûsâ kızgın ve üzgün dönüp levhaları attı ve kardeşini başından tuttu (A'râf 150). Hârûn'un özrünü dinleyince “Rabbim! Beni ve kardeşimi bağışla, bizi rahmetine koy” diye dua etti (A'râf 151). Öfkesi yatışınca levhaları aldı; onlarda Rablerinden korkanlar için doğru yol ve rahmet vardı (A'râf 154). Kıssa, tevhidin korunmasındaki hassasiyeti ve peygamberin merhametini anlatır. Kaynak: Kur'an-ı Kerim (A'râf suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Hârûn (a.s.) ---
  (44, 'Hz. Hârûn (a.s.) — Kardeşe Vezir, Davete Ortak', 'Peygamberler', 4,
      "Mûsâ'nın duasıyla peygamberlik ve vezirlik verilen, dili düzgün ve yumuşak huylu kardeşin kıssası.",
      "Mûsâ (a.s.), peygamberlik görevini yüklenirken Rabbine şöyle yalvardı: “Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Hârûn'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl.” (Tâhâ 25-32) Kasas suresi onun gerekçesini de anar: “Kardeşim Hârûn'un dili benimkinden daha düzgündür; onu beni destekleyen bir yardımcı olarak benimle gönder.” Allah, “Seni kardeşinle destekleyeceğiz” buyurdu (Kasas 34-35). Tâhâ 36'da “İstediğin sana verildi” müjdesi gelir. Meryem suresi, rahmetinden kardeşi Hârûn'u ona peygamber olarak bağışladığını bildirir (Meryem 53); Furkân suresi de Hârûn'un Mûsâ'ya vezir kılındığını söyler (Furkân 35). İki kardeş birlikte Firavun'a gitti; Allah onlara “Korkmayın, Ben sizinle beraberim” dedi (Tâhâ 45-46). Bu kıssa, hak davada dayanışmanın ve görev paylaşımının kıymetini gösterir. Kaynak: Kur'an-ı Kerim (Tâhâ, Kasas, Meryem, Furkân suresi); Diyanet İslam Ansiklopedisi."),
  (45, 'Hz. Hârûn (a.s.) — Buzağı Fitnesinde Sorumluluk', 'Peygamberler', 5,
      "Kavmi buzağıya yönelince uyarıda bulunan Hârûn, ayrılığa sebep olmaktan çekindiğini söyledi ve Mûsâ ile birlikte bağışlanma diledi.",
      "Mûsâ (a.s.) Tûr'a giderken kardeşi Hârûn'u yerine bırakmıştı (A'râf 142). Kavmi, ziynetlerden yapılmış bir buzağıya yönelince Hârûn onlara önceden şöyle demişti: “Ey milletim! Siz bununla sınanıyorsunuz. Sizin gerçek Rabbiniz Rahmân'dır; bana uyun, emrime itaat edin.” Onlar ise “Mûsâ bize dönene kadar buna bağlı kalmaktan vazgeçmeyeceğiz” dediler (Tâhâ 90-91). Mûsâ öfkeyle dönüp Hârûn'a hesap sorunca Hârûn, “Ey annemin oğlu! Saçımdan sakalımdan tutma. Doğrusu beni zayıf buldular, neredeyse beni öldüreceklerdi. Düşmanları bana güldürme” dedi (A'râf 150). Başka bir ayette gerekçesi şöyle anılır: “İsrâiloğulları arasına ayrılık koydun demenden korktum” (Tâhâ 94). Mûsâ onun özrünü anlayınca “Rabbim! Beni ve kardeşimi bağışla, bizi rahmetine koy; Sen merhametlilerin en merhametlisisin” diye dua etti (A'râf 151). Kıssa, toplumu birlik içinde tutma kaygısının, hak ile hikmetin birlikte gözetilmesini gerektirdiğini hatırlatır. Kaynak: Kur'an-ı Kerim (Tâhâ, A'râf suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Zülkifl (a.s.) ---
  (46, 'Hz. Zülkifl (a.s.) — Sabredenlerden Bir Peygamber', 'Peygamberler', 3,
      "Kur'an'da kısaca anılan Zülkifl, sabredenlerden ve iyilerden sayıldı.",
      "Zülkifl (a.s.), Kur'an'da iki yerde, kısa ve vurgulu bir üslupla anılan peygamberlerdendir. Enbiyâ suresinde şöyle buyurulur: “İsmâil, İdrîs ve Zülkifl hakkında anlattığımızı da an; onların her biri sabredenlerdendi. Onları rahmetimizin içine aldık; doğrusu onlar iyilerdendi.” (Enbiyâ 85-86) Ayetler, onun hayatının ayrıntısını vermez; ama Allah'ın onda öne çıkardığı nitelik açıktır: sabır. Sabır, Kur'an'ın peygamberlerde en çok vurguladığı değerlerdendir ve Allah sabredenleri rahmetine alır. Sâd suresinde ise Zülkifl, diğer seçkin kullarla birlikte anılır ve “Hepsi iyilerdendir” buyurulur (Sâd 48). Ayetlerde onun İsmâil ve İdrîs ile birlikte anılması, bu kulların sabır ve iyilik çizgisinde birleştiğini gösterir. Bu kısa anlatımdan alınacak ders, bir kulun değerinin çok anlatılmasında değil, Allah katında sabır ve iyilikte olduğudur. Bu kıssayı okumaktaki amacımız da onların örnekliğini anmak ve kendi sınavlarımızda sabra tutunmaktır. Kaynak: Kur'an-ı Kerim (Enbiyâ, Sâd suresi); Diyanet İslam Ansiklopedisi."),
  (47, 'Hz. Zülkifl (a.s.) — Kimliği ve Kur\'an\'ın Sustuğu Yer', 'Peygamberler', 3,
      "Kur'an Zülkifl hakkında ayrıntı vermez; bu sessizlik, bilgiyi uydurmadan ibret almayı öğretir.",
      "Kur'an Zülkifl (a.s.) hakkında yalnızca iki kısa ayet grubunda bilgi verir (Enbiyâ 85-86; Sâd 48). “Zülkifl” adı ve kimliği, İslam âlimleri arasında farklı yorumlara konu olmuştur; ismin “kefil olan, pay sahibi” gibi anlamlarda yorumlandığı, hangi peygamberle özdeşleştirileceği konusunda ise görüş ayrılığı bulunduğu bilinir. Bu konuda kesin bir bilgi yoktur. Kur'an'ın verdiği kadarıyla yetinmek, güvenilir yoldur: O, sabredenlerden, iyilerden ve seçkin kullardandır. Sâd suresinde, İsmâil ve Elyesâ ile birlikte “an” emriyle zikredilir (Sâd 48); bu emir, peygamberlerin hatırasını canlı tutmayı ve onlardan ibret almayı öğütler. Kur'an kıssaları tarih anlatmak için değil, kalpleri eğitmek için anlatır; bu yüzden isim ve ayrıntı azlığı, öğüdün azlığı anlamına gelmez. Bu kıssa bize, bilmediğimiz konuda susmanın ve kaynaksız rivayetlerden kaçınmanın da bir edep olduğunu hatırlatır. Kaynak: Kur'an-ı Kerim (Enbiyâ, Sâd suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Dâvûd (a.s.) ---
  (48, 'Hz. Dâvûd (a.s.) — Câlût\'a Karşı Zafer', 'Peygamberler', 5,
      "Talût'un ordusu içinde Câlût'u yenen Dâvûd'a Allah hükümranlık ve hikmet verdi.",
      "Mûsâ'dan sonra İsrâiloğullarının ileri gelenleri peygamberlerinden bir hükümdar istedi. Peygamberleri, “Allah size Talût'u hükümdar gönderdi” dedi; Talût'un bilgice ve bedence güçlendirildiğini bildirdi (Bakara 246-247). Talût ordusuyla yola çıkınca, “Allah sizi bir ırmakla deneyecek; ondan içen benden değildir, bir avuçtan fazlasını içmeyen bendendir” dedi; çok azı hariç hepsi içti (Bakara 249). Kalanlar Câlût ve ordusu karşısında “Bugün onlara karşı gücümüz yok” dediler; Allah'a kavuşacağına kesin inananlar ise “Nice az topluluk, Allah'ın izniyle çok topluluğa üstün gelmiştir. Allah sabredenlerle beraberdir” dedi (Bakara 249). Onlar, “Rabbimiz! Bize sabır ver, sebatımızı artır, kâfirlere karşı bize yardım et” diye dua ettiler (Bakara 250). Allah'ın izniyle düşmanı bozguna uğrattılar; Dâvûd, Câlût'u öldürdü ve Allah ona hükümranlık ve hikmet verdi, dilediğinden öğretti (Bakara 251). Kıssa, sayıdan çok sabır, disiplin ve duanın belirleyici olduğunu gösterir. Kaynak: Kur'an-ı Kerim (Bakara suresi); Diyanet İslam Ansiklopedisi."),
  (49, 'Hz. Dâvûd (a.s.) — Zebûr, Tesbih ve Demir', 'Peygamberler', 5,
      "Zebûr'u alan, sesiyle dağları ve kuşları tesbihe katan, demir işlemeyi öğrenen peygamber ve kul.",
      "Allah Dâvûd'a Zebûr'u verdi (Nisâ 163). Onu “güçlü kulumuz” diye anar ve “o, daima Allah'a yönelirdi” buyurur (Sâd 17). Akşam sabah onunla birlikte tesbih eden dağlar ve kuşlar emrine verilmişti; her biri Allah'a yönelmekteydi (Sâd 18; Enbiyâ 79). Sebe suresinde, “Ey dağlar ve kuşlar! Dâvûd tesbih ettikçe siz de onu tekrarlayın” buyrulur ve demirin onun için yumuşatıldığı bildirilir: “Geniş zırhlar yap, dokumasını sağlam tut. Yararlı iş işleyin; doğrusu Ben yaptıklarınızı görürüm.” (Sebe 10-11) Enbiyâ suresine göre Allah ona, savaşta insanları korumak için zırh yapma sanatını öğretti ve “Artık şükreder misiniz?” diye sordu (Enbiyâ 80). Hükümranlığını kuvvetlendirdi, ona hikmet ve kesin hüküm yeteneği verdi (Sâd 20). Dâvûd ailesine “Şükredin” buyruldu (Sebe 13). Bu kıssada ibadet, emek ve şükür birbirini tamamlar: Peygamber hem Allah'ı anan hem de toplumun ihtiyacına çalışan bir kuldur. Kaynak: Kur'an-ı Kerim (Nisâ, Sâd, Sebe, Enbiyâ suresi); Diyanet İslam Ansiklopedisi."),
  (50, 'Hz. Dâvûd (a.s.) — Adalet ve Tövbe', 'Peygamberler', 5,
      "İki davacının hikâyesiyle sınandığını anlayan Dâvûd, istiğfar etti ve tövbesi kabul edildi.",
      "Sâd suresi, Dâvûd'un yanına duvardan tırmanıp giren iki davacının haberini anlatır. Dâvûd ürkünce onlar, “Korkma; birbirinin hakkına tecavüz etmiş iki davacıyız. Aramızda adaletle hükmet, haktan ayrılma, bizi doğru yola ilet” dediler. Biri, “Bu kardeşimin doksan dokuz dişi koyunu var, benim bir tek dişi koyunum var; onu da bana ver dedi” diye şikâyet etti (Sâd 21-23). Dâvûd, “Sana haksızlık etmiş” hükmünü verdikten sonra, kendisini imtihan ettiğimizi anladı; Rabbinden bağışlanma diledi, eğilip secdeye kapandı ve Allah'a yöneldi. Allah da onu bağışladı; katında yakınlığı ve güzel bir dönüş yeri olduğunu bildirdi (Sâd 24-25). Ardından şu buyruk geldi: “Ey Dâvûd! Seni yeryüzünde halife kıldık. İnsanlar arasında adaletle hükmet, hevâya uyma.” (Sâd 26) Enbiyâ 78-79'da Dâvûd ve Süleyman'ın bir ekin hakkındaki hükmü de anılır: Allah her ikisine hüküm ve ilim verdi. Bu kıssa, yöneticinin adaletle hükmetmesinin ve imtihanı fark edince hemen Allah'a dönmesinin örneğidir. Kaynak: Kur'an-ı Kerim (Sâd, Enbiyâ suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Süleyman (a.s.) ---
  (51, 'Hz. Süleyman (a.s.) — Nimet ve Şükür', 'Peygamberler', 5,
      "Dâvûd'a varis olan Süleyman'a rüzgâr, kuş dili ve geniş bir hükümranlık verildi; o bunu şükürle karşıladı.",
      "Allah, Dâvûd'a ve Süleyman'a ilim verdi; ikisi de “Bizi mümin kullarının çoğundan üstün kılan Allah'a hamdolsun” dedi. Süleyman, Dâvûd'a varis oldu ve şöyle dedi: “Ey insanlar! Bize kuş dili öğretildi ve bize her şeyden bolca verildi. Doğrusu bu apaçık bir lütuftur.” (Neml 15-16) Süleyman şöyle dua etmişti: “Rabbim! Beni bağışla, bana benden sonra kimsenin ulaşamayacağı bir hükümranlık ver; Sen daima bağışta bulunansın.” Allah rüzgârı onun buyruğuna verdi; gündüz estiğinde bir aylık mesafeye gider, akşam bir aylık mesafeden gelirdi. Bina yapan ve dalgıçlık eden cinleri de emrine verdi (Sâd 35-38; Sebe 12-13). “İşte bizim bağışımız budur, ister ver ister tut, hesapsızdır” buyruldu (Sâd 39). Süleyman'ın vefatı da ibretlidir: Değneğini yiyen bir kurt onun öldüğünü cinlere fark ettirdi; gaybı bilselerdi alçaltıcı azapta kalmazlardı (Sebe 14). Gücün de gaybın da Allah'a ait olduğu böylece görüldü. Kaynak: Kur'an-ı Kerim (Neml, Sâd, Sebe suresi); Diyanet İslam Ansiklopedisi."),
  (52, 'Hz. Süleyman (a.s.) — Karınca Vadisi ve Hüdhüd', 'Peygamberler', 5,
      "Karıncanın uyarısına gülümseyip şükreden, hüdhüdün getirdiği habere ise delil arayan bir hükümdar.",
      "Süleyman'ın cinlerden, insanlardan ve kuşlardan oluşan ordusu toplanmıştı. Karıncalar vadisine geldiklerinde bir karınca, “Ey karıncalar! Yuvalarınıza girin, Süleyman'ın ordusu farkına varmadan sizi ezmesin” dedi. Süleyman onun sözüne hafifçe güldü ve “Rabbim! Bana ve anne babama verdiğin nimete şükretmemi, hoşnut olacağın iyi işi yapmamı sağla; rahmetinle beni salih kullarının arasına koy” diye dua etti (Neml 17-19). Süleyman kuşları yoklarken hüdhüdü göremeyince, “Ya bana açık bir delil getirir ya da cezalandırırım” dedi. Hüdhüd kısa süre sonra gelip, “Senin bilmediğini öğrendim; Sebe'den sana kesin bir haber getirdim” dedi. Büyük bir tahta sahip bir kadının ve kavminin Allah'ı bırakıp güneşe secde ettiğini bildirdi (Neml 20-24). Süleyman, haberin doğruluğunu hemen kabul etmedi: “Doğru mu söyledin yoksa yalancılardan mı oldun, bakacağız” dedi (Neml 27). Kıssa, güç sahibi bir kişinin bile küçük bir varlığa kulak vermesini ve bilgiyi doğrulama sorumluluğunu öğretir. Kaynak: Kur'an-ı Kerim (Neml suresi); Diyanet İslam Ansiklopedisi."),
  (53, 'Hz. Süleyman (a.s.) — Sebe Melikesine Davet', 'Peygamberler', 6,
      "Süleyman'ın mektubuyla başlayan davet, melikenin 'Âlemlerin Rabbi'ne teslim oldum' demesiyle sonuçlandı.",
      "Süleyman, Sebe halkına bir mektup gönderdi. Sebe melikesi ileri gelenlere şöyle dedi: “Bana önemli bir mektup bırakıldı. Süleyman'dandır, Bismillâhirrahmânirrahîm ile başlıyor: Bana karşı baş kaldırmayın, teslim olarak gelin.” (Neml 29-31) Melike, danışmadan karar vermedi; bir hediye gönderip elçilerin ne ile döneceğine bakmak istedi (Neml 32-35). Süleyman hediyeyi reddetti: “Bana mal ile mi yardım etmek istiyorsunuz? Allah'ın bana verdiği, size verdiğinden daha hayırlıdır.” (Neml 36) Sonra tahtın getirilmesini istedi; Kitap bilgisine sahip biri, “Gözünü açıp kapamadan ben onu sana getiririm” dedi. Süleyman tahtı yanında görünce, “Bu, şükür mü edeceğim yoksa nankörlük mü edeceğim diye beni sınayan Rabbimin lütfundandır” dedi (Neml 38-40). Melike, camdan yapılmış parlak salonu su zannedip eteğini çekince Süleyman durumu açıkladı. Melike, “Rabbim! Ben kendime yazık etmişim; Süleyman'la birlikte âlemlerin Rabbi Allah'a teslim oldum” dedi (Neml 44). Kur'an kraliçenin adını anmaz; “Sebe melikesi” der. Kaynak: Kur'an-ı Kerim (Neml suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. İlyâs (a.s.) ---
  (54, 'Hz. İlyâs (a.s.) — Baal\'a Karşı Tevhid Çağrısı', 'Peygamberler', 4,
      "İlyâs, kavmini Baal'a tapmayı bırakıp tek Rablerine dönmeye çağırdı; kavmi onu yalanladı.",
      "Allah, Sâffât suresinde İlyâs'ı peygamberler arasında anar: “Doğrusu İlyâs da peygamberlerdendir.” (Sâffât 123) O, kavmine şöyle demişti: “Allah'a karşı gelmekten sakınmaz mısınız? Biçim verenlerin en güzeli olan, sizin de Rabbiniz, önceki babalarınızın da Rabbi olan Allah'ı bırakıp da Baal putuna mı yalvarıyorsunuz?” (Sâffât 124-126) Ayet, kavmin sapmasını tek bir soruyla gösterir: En güzel yaratıcıyı bırakıp bir puta yönelmek. Soru, kavme iki şeyi hatırlatır: Putlar hiçbir şey yaratmamıştır; yaratıcı ise hem onların hem de atalarının Rabbidir. Kavmi ise onu yalanladı; bu yüzden Allah'ın ihlaslı kulları dışında hepsi azaba getirilecekti (Sâffât 127-128). En'âm suresinde de İlyâs, Zekeriyyâ, Yahyâ ve Îsâ ile birlikte salihlerden sayılır (En'âm 85). Kıssa, kısa olmakla birlikte, hakka davetin cesur, açık ve akla seslenen bir üslupla yapılabileceğini gösterir. Kaynak: Kur'an-ı Kerim (Sâffât, En'âm suresi); Diyanet İslam Ansiklopedisi."),
  (55, 'Hz. İlyâs (a.s.) — Hatırası Bırakılan Kul', 'Peygamberler', 3,
      "Kavmi yalanlasa da İlyâs'a Allah tarafından kıyamete kadar sürecek bir hatıra ve selam bırakıldı.",
      "İlyâs'ın kıssası Sâffât suresinin son bölümünde şöyle tamamlanır: “Sonra gelenler içinde, ‘İlyâs'a selam olsun’ diye bir ün bıraktık. Doğrusu Biz iyileri böylece mükâfatlandırırız. O, inanmış kullarımızdandı.” (Sâffât 129-132) Ayetler, kavminin onu yalanladığını; buna rağmen Allah'ın onu mükâfatlandırdığını bildirir. Bu mükâfat, dünyada hatırasının güzel anılması ve ona selam gönderilmesidir. Kur'an, İlyâs'ın sonu hakkında ayrıntı vermez; yaşadığı yer, ne zaman vefat ettiği veya göğe alınıp alınmadığı gibi konularda ayetlerde bir bilgi yoktur. Bu konularda kaynaksız rivayetlere itibar etmeyip Kur'an'ın verdiğiyle yetinmek doğrudur. Allah'ın “iyileri böyle mükâfatlandırırız” buyurması, bu mükâfatın her samimi kul için geçerli olduğunu da bildirir. Önemli olan, ayette vurgulanan niteliktir: İlyâs “inanmış kullardandı” ve hatırası hayırla yaşatıldı. Hak yolunda yalnız kalmak, Allah katında bir eksiklik değil; ihlasla yürüyenlerin nasibidir. Kaynak: Kur'an-ı Kerim (Sâffât suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Elyesâ (a.s.) ---
  (56, 'Hz. Elyesâ (a.s.) — Hidayet Zincirinin Bir Halkası', 'Peygamberler', 3,
      "Elyesâ, Kur'an'ın andığı peygamberler silsilesinde âlemlere üstün kılınan seçkin kullardandır.",
      "Elyesâ (a.s.), Kur'an'da iki yerde, kısa biçimde anılan peygamberlerdendir. En'âm suresi, Allah'ın doğru yola eriştirdiği peygamberleri sayar: “Daha önce Nûh'u ve soyundan Dâvûd'u, Süleyman'ı, Eyyûb'u, Yûsuf'u, Mûsâ'yı ve Hârûn'u; Zekeriyyâ'yı, Yahyâ'yı, Îsâ'yı ve İlyâs'ı; İsmâil'i, Elyesâ'yı, Yûnus'u ve Lût'u da -ki hepsini âlemlere üstün kıldık- doğru yola eriştirdik.” (En'âm 84-86) Ardından Allah, bunların atalarından, soylarından ve kardeşlerinden bir kısmını da seçtiğini ve doğru yola ilettiğini söyler (En'âm 87). Bu, Allah'ın kullarından dilediğini eriştirdiği yoldur (En'âm 88). Elyesâ'nın adı bu silsilenin içinde geçer; yani o da vahiy zincirinin halkalarındandır. Kur'an bu kullara “kitap, hüküm ve peygamberlik” verildiğini bildirir (En'âm 89) ve Resûlullah'a “Onların yoluna uy” der (En'âm 90). Elyesâ'dan alacağımız ders, ismi az geçse de peygamberlerin tek bir hakikatin elçileri olduğudur. Kaynak: Kur'an-ı Kerim (En'âm suresi); Diyanet İslam Ansiklopedisi."),
  (57, 'Hz. Elyesâ (a.s.) — İyiler Arasında Anılan Kul', 'Peygamberler', 3,
      "Sâd suresi Elyesâ'yı İsmâil ve Zülkifl'le birlikte anıp 'hepsi iyilerdendir' der.",
      "Sâd suresi, sabır ve duayla öne çıkan peygamberlerin anlatıldığı kıssalardan sonra Resûlullah'a şöyle buyurur: “İsmâil'i, Elyesâ'yı, Zülkifl'i de an. Hepsi iyilerdendir.” (Sâd 48) Aynı sure, bu peygamberleri hayat hikâyeleriyle değil, Allah'a yönelişleriyle öne çıkarır; çünkü hepsinin ortak noktası tevhid ve salih ameldir. Bu kısa ayet, Elyesâ'nın Allah katındaki konumunu özetler: O, iyilerdendir ve ismi, ibret için hatırlanması istenen bir kuldur. Kur'an, onun kavmi, mucizeleri ya da yaşadığı yer hakkında ayrıntı vermez; bu konudaki bilgiler Kur'an'da yer almadığı için kesin olarak aktarılamaz. “An” emri iki anlam taşır: Bir yandan o peygamberlerin hatırasını yaşatmak, bir yandan da onların güzel ahlakını örnek almak. Allah katında kıymetli olan, anlatılan ayrıntının çokluğu değil, kulun iyiliği ve Allah'a bağlılığıdır. Kaynak: Kur'an-ı Kerim (Sâd, En'âm suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Yûnus (a.s.) ---
  (58, 'Hz. Yûnus (a.s.) — Balığın Karnında Dua', 'Peygamberler', 5,
      "Öfkeyle kavminden ayrılan Yûnus, balığın karnındaki karanlıklarda Allah'ı tesbih etti ve kurtuldu.",
      "Yûnus (a.s.), Kur'an'da “Zünnûn” (balık sahibi) diye de anılır. Enbiyâ suresine göre o, öfkelenerek giderken kendisini sıkıntıya sokmayacağımızı sanmıştı (Enbiyâ 87). Sâffât suresi hâlini şöyle anlatır: Dolu bir gemiye kaçtı, gemidekilerle kura çekti ve yenilenlerden oldu, denize atıldı. Kendini kınarken onu bir balık yuttu (Sâffât 139-142). Karanlıklar içinde şöyle seslendi: “Senden başka ilâh yoktur, Sen münezzehsin, doğrusu ben haksızlık edenlerden oldum.” Allah onun duasına cevap verip onu üzüntüden kurtardı; “İnananları böyle kurtarırız” buyurdu (Enbiyâ 87-88). Eğer Allah'ı tesbih edenlerden olmasaydı, diriltilecekleri güne kadar balığın karnında kalacaktı (Sâffât 143-144). Halsiz hâlde sahile çıkarıldı ve üzerine geniş yapraklı bir bitki bitirildi (Sâffât 145-146). Kalem suresi, Resûlullah'a “Balık sahibi gibi olma; o pek üzgün olarak Rabbine seslenmişti” diyerek sabrı öğütler (Kalem 48-50). Kaynak: Kur'an-ı Kerim (Enbiyâ, Sâffât, Kalem suresi); Diyanet İslam Ansiklopedisi."),
  (59, 'Hz. Yûnus (a.s.) — İman Eden Kent', 'Peygamberler', 4,
      "Yûnus'un kavmi iman etti ve Allah rezil edici azabı onlardan kaldırdı.",
      "Allah, Yûnus'u yüz bin veya daha fazla kişiye peygamber olarak gönderdi. Sonunda ona inandılar; Allah da onları belli bir süreye kadar geçindirdi (Sâffât 147-148). Yûnus suresi bu olayı şöyle anar: “Bir kent halkı inanmalı değil miydi ki imanları kendilerine fayda versin! Yûnus'un kavmi inandığı zaman, dünya hayatında rezilliği gerektiren azabı onlardan kaldırdık ve onları bir süre daha geçindirdik.” (Yûnus 98) Bu ayet, imanın tövbe ve samimiyetle tam zamanında gelmesinin sonucunu gösterir; çünkü Kur'an'a göre işin işten geçtiği anda gelen iman fayda vermez. Yûnus'un kavmi ise Allah'a içtenlikle döndü ve bu dönüş karşılık buldu. Kıssa, hem peygamberin sabra çağrıldığını hem de tövbenin kapısının açık olduğunu öğretir. Allah, bir kulun, bir kavmin içtenlikle dönüşünü karşılıksız bırakmaz. Peygamberin sabrı ve kavmin pişmanlığı birlikte düşünüldüğünde, Allah'ın merhametinin geniş olduğu görülür. Kaynak: Kur'an-ı Kerim (Sâffât, Yûnus suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Zekeriyyâ (a.s.) ---
  (60, 'Hz. Zekeriyyâ (a.s.) — Gizli Dua, Güzel Müjde', 'Peygamberler', 5,
      "İhtiyarlığında, eşi kısırken evlat için gizlice dua eden Zekeriyyâ, Yahyâ müjdesine kavuştu.",
      "Meryem suresi, Zekeriyyâ'nın kıssasını Allah'ın rahmetinin anılması olarak başlatır (Meryem 2). Zekeriyyâ, Meryem'in bakımını üstlenmişti; mihraba her girişinde yanında bir rızık bulur ve Allah'ın katından olduğunu duyardı (Âl-i İmrân 37). Orada Rabbine şöyle dua etti: “Ya Rabbi! Bana katından temiz bir soy bağışla, Sen duayı işitirsin.” (Âl-i İmrân 38) Meryem suresinde duası şöyle aktarılır: “Rabbim! Kemiklerim zayıfladı, saçlarım ağardı. Sana dua etmekle bedbaht olmadım. Benden sonra yakınlarımın durumundan korkuyorum, eşim de kısırdır. Bana katından bir varis bağışla.” (Meryem 3-6) Başka bir yerde de şöyle yalvardığı bildirilir: “Rabbim! Beni tek başıma bırakma; Sen varislerin en hayırlısısın.” (Enbiyâ 89) Melekler, mihrabında namaz kılarken ona Yahyâ'yı müjdelediler (Âl-i İmrân 39). Dua edenler, çaresiz görünen şartlarda da Allah'a yönelmenin değerini ondan öğrenir. Kaynak: Kur'an-ı Kerim (Meryem, Âl-i İmrân, Enbiyâ suresi); Diyanet İslam Ansiklopedisi."),
  (61, 'Hz. Zekeriyyâ (a.s.) — Alamet ve Sükût', 'Peygamberler', 4,
      "Zekeriyyâ'ya müjdenin alameti, sağlıklıyken üç gün insanlarla konuşamamak oldu; bu günlerde Allah'ı tesbihe devam etti.",
      "Allah, Zekeriyyâ'ya Yahyâ'yı müjdeledi ve bu adı daha önce kimseye vermediğini bildirdi (Meryem 7). Zekeriyyâ hayretle, “Rabbim! Eşim kısır, ben de iyice yaşlanmışken nasıl oğlum olabilir?” dedi. Allah, “Rabbin böyle buyurdu; bu Bana kolaydır, nitekim sen yokken daha önce seni yaratmıştım” diye cevapladı (Meryem 8-9). Âl-i İmrân suresinde de aynı hayret ve “Allah dilediğini yapar” cevabı geçer (Âl-i İmrân 40). Zekeriyyâ bir alamet isteyince şu cevabı aldı: “Senin alametin, sağlıklıyken üç gün üç gece insanlarla konuşamamandır.” (Meryem 10) Âl-i İmrân'da bu süre içinde işaretle anlaşma dışında konuşmayacağı, Rabbini çok anması ve sabah akşam tesbih etmesi söylenir (Âl-i İmrân 41). Mabetten çıkıp kavmine “Sabah akşam Allah'ı tesbih edin” diye işaret etti (Meryem 11). Allah, eşini de doğum yapacak hâle getirdi; ikisi de iyi işlerde yarışan, umut ve korkuyla yalvaran kullardı (Enbiyâ 90). Kaynak: Kur'an-ı Kerim (Meryem, Âl-i İmrân, Enbiyâ suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Yahyâ (a.s.) ---
  (62, 'Hz. Yahyâ (a.s.) — Müjdelenen Peygamber', 'Peygamberler', 4,
      "Doğumundan önce adı ve vasıfları bildirilen Yahyâ, Allah'ın kelimesini doğrulayan bir peygamberdi.",
      "Yahyâ (a.s.), Zekeriyyâ'nın duasına karşılık bağışlanan oğuldu. Allah, Zekeriyyâ'ya, “Sana Yahyâ adında bir oğlan müjdeliyoruz; bu adı daha önce kimseye vermemiştik” buyurdu (Meryem 7). Âl-i İmrân suresinde melekler ona şöyle seslendi: “Allah sana, Allah'ın kelimesini (Îsâ'yı) doğrulayan, efendi, iffetli, iyilerden bir peygamber olarak Yahyâ'yı müjdeler.” (Âl-i İmrân 39) Burada üç vasıf öne çıkar: Allah'tan gelen kelimeyi tasdik, halkın seçkini olma ve iffet. Yahyâ'nın Îsâ'ya inanıp onu doğrulayacağı bildirilir. Enbiyâ suresi, Allah'ın Zekeriyyâ'nın duasını kabul ettiğini ve ona Yahyâ'yı bağışladığını teyit eder; bu ailenin iyi işlerde yarışan, Allah'a umut ve korkuyla yalvaran kimseler olduğunu belirtir (Enbiyâ 90). Kıssa, duanın karşılığının Allah'ın dilediği zamanda ve dilediği biçimde geldiğini; müjdelenen evladın bir hediye olduğu kadar bir emanet de olduğunu hatırlatır. Kaynak: Kur'an-ı Kerim (Meryem, Âl-i İmrân, Enbiyâ suresi); Diyanet İslam Ansiklopedisi."),
  (63, 'Hz. Yahyâ (a.s.) — Kitaba Kuvvetle Sarıl', 'Peygamberler', 4,
      "Çocukken hikmet verilen, anne babasına iyilik eden ve selam ile anılan peygamber.",
      "Allah, Yahyâ'ya şu emri verdi: “Ey Yahyâ! Kitaba kuvvetle sarıl.” Daha çocukken ona hikmet, katımızdan şefkat ve temizlik verdi; o Allah'tan sakınan, anne babasına iyi davranan biriydi, zorba ve asi değildi (Meryem 12-14). Ayetler, kitaba bağlılığın bir gevşeklik değil, güç ve kararlılık gerektiren bir tavır olduğunu gösterir. “Hikmet” doğru hüküm ve isabetli kavrayış; “hanân” yumuşak yürekliliktir. Bu iki vasıf bir arada, bir davetçide aranan özelliklerdir. Anne babaya iyilik, ayette özellikle zikredilir; çünkü peygamberlik makamı bile bu hakkı hafifletmez. Meryem suresi, onun kıssasını şu selamla bitirir: “Doğduğu günde, öleceği günde ve dirileceği günde ona selam olsun.” (Meryem 15) Kur'an, Yahyâ'nın nasıl vefat ettiğini anlatmaz; ayrıntı konusunda kaynaksız rivayetlere itibar edilmez. Önemli olan, onun hayatının her evresinde Allah'ın selamıyla anılmasıdır. Kaynak: Kur'an-ı Kerim (Meryem suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Îsâ (a.s.) ---
  (64, 'Hz. Îsâ (a.s.) — Meryem\'e Müjde ve Doğum', 'Peygamberler', 6,
      "Allah, Meryem'e kendinden bir kelimeyi müjdeledi; Îsâ, babasız olarak dünyaya geldi.",
      "Melekler Meryem'e şöyle demişti: “Allah seni seçip temizledi, dünyaların kadınlarından üstün kıldı.” (Âl-i İmrân 42) Sonra, “Allah sana kendinden bir kelimeyi, adı Meryem oğlu Îsâ Mesîh olan birini müjdeler; dünyada ve ahirette şerefli, Allah'a yakın kılınanlardandır. Beşikte de yetişkinken de insanlarla konuşacaktır” dediler (Âl-i İmrân 45-46). Meryem, “Bana bir beşer dokunmamışken nasıl çocuğum olur?” diye sordu; “Allah dilediğini böyle yaratır. Bir işe hükmetti mi ona sadece ‘ol’ der, o da olur” cevabı verildi (Âl-i İmrân 47). Meryem suresinde Cebrâîl, ona tam bir insan olarak göründü; Meryem “Eğer Allah'tan sakınan biriysen, senden Rahmân'a sığınırım” dedi. Cebrâîl, “Ben sana temiz bir oğul bağışlamak için Rabbinin gönderdiği elçiyim” cevabını verdi (Meryem 16-21). Doğum sancısı Meryem'i bir hurma ağacının dibine götürdü; ona şu ses duyuldu: “Sakın üzülme! Hurma ağacını kendine doğru silkele, üstüne taze hurma dökülsün. Ye, iç, gözün aydın olsun.” (Meryem 22-26) Îsâ'nın doğumu, Allah'ın dilediğini kolayca yaratabileceğinin delilidir. Kaynak: Kur'an-ı Kerim (Âl-i İmrân, Meryem suresi); Diyanet İslam Ansiklopedisi."),
  (65, 'Hz. Îsâ (a.s.) — Beşikte Konuşma ve Mucizeler', 'Peygamberler', 6,
      "Îsâ, beşikte 'Ben Allah'ın kuluyum' dedi; Allah'ın izniyle hastaları iyileştirdi ve mucizeler gösterdi.",
      "Meryem çocuğu kavmine getirince onlar suçlayıcı sözler söyledi. Meryem çocuğu işaret etti; “Beşikteki çocukla nasıl konuşuruz?” dediler. Çocuk şöyle dedi: “Ben Allah'ın kuluyum. O bana kitap verdi ve beni peygamber yaptı; nerede olursam olayım beni mübarek kıldı. Yaşadığım müddetçe namaz kılmamı ve zekât vermemi emretti. Anneme iyi davranmamı da emretti; beni zorba ve bedbaht yapmadı.” (Meryem 27-32) Allah ona Kitap'ı, hikmeti, Tevrat'ı ve İncil'i öğretti (Âl-i İmrân 48). İsrâiloğullarına gönderilen bu peygamber, Rabbinden bir delil getirdiğini söyledi: Çamurdan kuş şekli yapıp ona üflediğinde Allah'ın izniyle kuş olur; Allah'ın izniyle anadan doğma körü ve alacalıyı iyileştirir, ölüleri diriltir (Âl-i İmrân 49; Mâide 110). Allah ona nimetini şöyle hatırlatır: “Seni Rûhulkudüs ile destekledim.” (Mâide 110) Îsâ, “Allah benim de Rabbim, sizin de Rabbinizdir; O'na kulluk edin, bu doğru yoldur” diyerek tevhidi tebliğ etti (Âl-i İmrân 50-51). Kaynak: Kur'an-ı Kerim (Meryem, Âl-i İmrân, Mâide suresi); Diyanet İslam Ansiklopedisi."),
  (66, 'Hz. Îsâ (a.s.) — Havariler, Sofra ve Yükseltilme', 'Peygamberler', 6,
      "Havarileri 'Allah'ın yardımcıları' oldu; Îsâ öldürülmedi, Allah onu kendi katına yükseltti.",
      "İsrâiloğullarından çoğunun inkârını hisseden Îsâ, “Allah yolunda yardımcılarım kimlerdir?” dedi. Havariler, “Biz Allah'ın yardımcılarıyız; Allah'a inandık, bizim müslüman olduğumuza şahit ol” dediler (Âl-i İmrân 52). Mâide suresinde havariler gökten bir sofra indirilmesini istedi; Îsâ onlara, “İnanıyorsanız Allah'tan sakının” dedi. Onlar, sofradan yemek, kalplerinin yatışması ve onun doğru söylediğini bilmek için istediklerini bildirdiler. Îsâ, “Allahım, Rabbimiz! Bize gökten bir sofra indir, o bizim için ve bizden sonrakiler için bayram ve Senden bir delil olsun” diye dua etti. Allah, “Ben onu size indireceğim” buyurdu ve inkâr edenlere ağır azabı bildirdi (Mâide 112-115). İnkâr edenlerin “Meryem oğlu Îsâ Mesîh'i öldürdük” demesi karşısında Kur'an şöyle der: Onu öldürmediler ve asmadılar; onlara öyle gösterildi. Kesin olan, Allah'ın onu kendi katına yükseltmiş olmasıdır (Nisâ 157-158; Âl-i İmrân 55). Îsâ, kendinden sonra gelecek ve adı Ahmed olan bir peygamberi müjdeledi (Saf 6). Kaynak: Kur'an-ı Kerim (Âl-i İmrân, Mâide, Nisâ, Saf suresi); Diyanet İslam Ansiklopedisi."),

  // --- Hz. Muhammed (s.a.v.) ---
  (67, 'Hz. Muhammed (s.a.v.) — Hira\'da İlk Vahiy', 'Peygamberler', 6,
      "'Oku!' emriyle başlayan vahiy, Hz. Muhammed'i (s.a.v.) insanlığa gönderilen son peygamber olarak görevlendirdi.",
      "Sahih rivayetlere göre Hz. Muhammed (s.a.v.), kırk yaşlarında Mekke yakınındaki Hira Mağarası'nda inzivadayken Cebrâîl (a.s.) gelerek ona “Oku!” dedi. Bu olay Kur'an'ın ilk inen ayetleriyle anılır: “Yaratan Rabbinin adıyla oku! O, insanı bir alak'tan yarattı. Oku! Rabbin en büyük kerem sahibidir; kalemle öğretendir, insana bilmediğini öğretendir.” (Alak 1-5) Kur'an, Ramazan ayında, kadir gecesinde indirilmeye başlandı (Bakara 185; Kadr 1). İlk vahyin ağırlığı Hz. Peygamber'i derinden etkiledi; sonraki vahiyler ona görevini hatırlattı: “Ey örtüye bürünen! Kalk da uyar. Rabbini yücelt. Giydiklerini temiz tut. Kötü şeyleri terk et. Yaptığın iyiliği çok görerek başa kakma. Rabbin için sabret.” (Müddessir 1-7) Müzzemmil suresi ona gece kalkıp ağır ağır Kur'an okumayı emreder ve “Doğrusu Biz sana ağır bir söz vahyedeceğiz” der (Müzzemmil 1-5). Kur'an yirmi üç yıl boyunca bölüm bölüm indi (İsrâ 106). Onun koruyucusu Allah'tır (Hicr 9). Kaynak: Kur'an-ı Kerim (Alak, Müddessir, Müzzemmil, Bakara, Kadr, İsrâ, Hicr suresi); Diyanet İslam Ansiklopedisi."),
  (68, 'Hz. Muhammed (s.a.v.) — Hicret ve Mağarada Sığınma', 'Peygamberler', 5,
      "Müşriklerin tuzaklarına karşı Mekke'den ayrılan Peygamber (s.a.v.) ve arkadaşına mağarada 'Üzülme, Allah bizimle' denildi.",
      "Mekke müşrikleri Hz. Peygamber'i (s.a.v.) bağlayıp hapsetmek, öldürmek veya Mekke'den çıkarmak için hile kurdu. Allah, “Onlar tuzak kurarken Allah da tuzaklarını boşa çıkarıyordu. Allah tuzak kuranların en hayırlısıdır” buyurur (Enfâl 30). Peygamber (s.a.v.), Allah'ın izniyle Mekke'den çıkarak Medine'ye hicret etti. Yolculuğun en çarpıcı anı, Tevbe suresinde şöyle anılır: “Ona yardım etmezseniz bilin ki, inkâr edenler onu Mekke'den çıkardıklarında, mağarada bulunan iki kişiden biri olarak Allah ona yardım etmişti. Arkadaşına, ‘Üzülme, Allah bizimle beraberdir’ diyordu. Allah da ona gönül huzuru verdi, görmediğiniz askerlerle onu destekledi.” (Tevbe 40) Ayette Resûlullah'ın arkadaşı, tefsirlere göre Ebû Bekir (r.a.)'dır. Bu olay, tebliğin zorluklarında bile sebeplere sarılıp Allah'a tevekkülü; gönül huzurunun Allah'ın bir lütfu olduğunu gösterir. Hicret, Medine'de İslam toplumunun kurulmasının kapısını aralamıştır. Kaynak: Kur'an-ı Kerim (Enfâl, Tevbe suresi); Diyanet İslam Ansiklopedisi."),
  (69, 'Hz. Muhammed (s.a.v.) — İsrâ ve Mi\'rac', 'Peygamberler', 5,
      "Bir gece Mescid-i Harâm'dan Mescid-i Aksâ'ya götürülen Peygamber (s.a.v.), Allah'ın büyük delillerini gördü.",
      "Kur'an, İsrâ olayını şu ayetle bildirir: “Kulunu bir gece Mescid-i Harâm'dan, çevresini mübarek kıldığımız Mescid-i Aksâ'ya, ona ayetlerimizden bir kısmını göstermek için götüren Allah'ın şanı yücedir. O, işitendir, görendir.” (İsrâ 1) Necm suresinde Peygamber'in (s.a.v.) Cebrâîl'i bir başka inişinde, sınırın sonunda gördüğü anlatılır; İslam âlimleri bu ayetleri Mi'rac ile ilişkilendirir: “Andolsun ki o, Cebrâîl'i sınırın sonunda başka bir inişinde de görmüştür. Orada Me'vâ cenneti vardır. Gözü oradan ne kaydı ne de onu aştı. Andolsun ki Rabbinin varlığının büyük delillerini gördü.” (Necm 13-18) Ayrıntıları sahih hadis kaynakları aktarır: Mi'rac gecesinde Hz. Peygamber'e beş vakit namaz farz kılınmıştır. Müslümanlar bu olayı bir mucize ve Allah'ın Peygamberine bir ikramı olarak kabul eder. Bu olay, namazın Allah katındaki yerini ve Peygamber'e verilen değeri hatırlatır. Kaynak: Kur'an-ı Kerim (İsrâ, Necm suresi); Diyanet İslam Ansiklopedisi."),
  (70, 'Hz. Muhammed (s.a.v.) — Âlemlere Rahmet ve Güzel Ahlak', 'Peygamberler', 6,
      "Kur'an, Hz. Muhammed'i (s.a.v.) âlemlere rahmet, güzel örnek ve peygamberlerin sonuncusu olarak tanıtır.",
      "Allah, Hz. Muhammed'e (s.a.v.) hitaben şöyle buyurur: “Biz seni ancak âlemlere rahmet olarak gönderdik.” (Enbiyâ 107) Onun ahlakı şu ayetle övülür: “Şüphesiz sen büyük bir ahlaka sahipsin.” (Kalem 4) Ahzâb suresi, “Allah'ın Elçisi sizin için, Allah'a ve ahiret gününe kavuşmayı umanlar ve Allah'ı çok anan kimseler için en güzel örnektir” der (Ahzâb 21). Tevbe suresi ona şöyle bir tarif verir: “İçinizden size, sıkıntıya düşmeniz kendisine ağır gelen, size düşkün, müminlere şefkatli ve merhametli bir peygamber gelmiştir.” (Tevbe 128) Duhâ suresi, vahyin bir süre kesildiği günlerin ardından onu teselli eder: “Rabbin seni ne bıraktı ne de sana darıldı. Ahiret senin için dünyadan daha hayırlıdır. Rabbin sana verecek ve sen hoşnut olacaksın. Seni öksüz bulup da barındırmadı mı?” (Duhâ 3-6) Ahzâb suresi onun peygamberlerin sonuncusu olduğunu bildirir (Ahzâb 40). Sonsuza dek geçerli rehberliği ve merhametiyle O, ümmetine ve bütün insanlığa güzel bir örnektir. Kaynak: Kur'an-ı Kerim (Enbiyâ, Kalem, Ahzâb, Tevbe, Duhâ suresi); Diyanet İslam Ansiklopedisi."),
];
